package com.example;

import org.eclipse.core.resources.ResourcesPlugin;
import org.eclipse.core.runtime.preferences.IEclipsePreferences;
import org.eclipse.core.runtime.preferences.InstanceScope;

public class ExampleClass {
    public void method() {
        IEclipsePreferences pref = InstanceScope.INSTANCE.getNode(ResourcesPlugin.PI_RESOURCES);
        // Different literal default value
        if (pref != null && (pref.getBoolean(ResourcesPlugin.PREF_AUTO_REFRESH, true) || pref.getBoolean(ResourcesPlugin.PREF_LIGHTWEIGHT_AUTO_REFRESH, true))) {
            System.out.println("Auto refresh is enabled (different default).");
        }
        // Different preference keys
        if (pref != null && (pref.getBoolean("some.other.key", false) || pref.getBoolean(ResourcesPlugin.PREF_LIGHTWEIGHT_AUTO_REFRESH, false))) {
            System.out.println("Auto refresh is enabled (different key).");
        }
        // Not an OR condition
        boolean autoRefresh = pref.getBoolean(ResourcesPlugin.PREF_AUTO_REFRESH, false);
        boolean lightweightRefresh = pref.getBoolean(ResourcesPlugin.PREF_LIGHTWEIGHT_AUTO_REFRESH, false);
        if (autoRefresh && lightweightRefresh) { // AND instead of OR
            System.out.println("Both refreshes enabled.");
        }
    }
}
